__NUXT_JSONP__("/inclusion/columnas/la_persistente_brecha_salarial_de_genero_en_mexico", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p){return {data:[{post:{slug:"la_persistente_brecha_salarial_de_genero_en_mexico",title:"La persistente brecha salarial de género en México",date:"2025-10-02T18:23:15.144Z",img:"https:\u002F\u002Fucarecdn.com\u002Fd83edafc-5d49-426e-8b1d-d078246767ce\u002F",autor:"Mónica Corona",medio:l,link:"https:\u002F\u002Fanimalpolitico.com\u002Fanalisis\u002Finvitades\u002Fla-persistente-brecha-salarial-de-genero-en-mexico",category:h,extracto:"Cerrar la brecha salarial de género es un asunto de justicia social, una necesidad económica, una inversión en nuestro futuro y un pilar para construir un México más equitativo y próspero para todas y todos.",toc:[],body:{type:i,children:[{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"Imagina esto: trabajas incansablemente, entregas todo tu esfuerzo y empeño en cada tarea, pero al final del mes, tu esfuerzo vale menos. ¿Por qué? Por el simple hecho de ser mujer."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"Esto no es una historia inventada, sino una realidad que vivimos las mujeres en México y a nivel mundial. La "},{type:b,tag:c,props:{},children:[{type:a,value:"brecha salarial de género"}]},{type:a,value:" es esa diferencia de ingresos entre hombres y mujeres, incluso cuando ocupan el mismo puesto. En ese sentido, "},{type:b,tag:c,props:{},children:[{type:a,value:"ser mujer continúa siendo un factor para ganar menos"}]},{type:a,value:", y no hablemos de ser madre, pues se agrava esa situación."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"En el caso concreto de nuestro país, y a pesar de los avances en políticas a favor de la equidad entre hombres y mujeres, la brecha salarial de género sigue siendo una realidad: de acuerdo con cifras de la última encuesta nacional de ingresos y gastos de los hogares (ENIGH) del INEGI, en 2024 "},{type:b,tag:c,props:{},children:[{type:a,value:"por cada peso que ganó un hombre, una mujer tan solo recibió 65 centavos."}]},{type:a,value:" Mientras un hombre recibió, en promedio, 12,016 pesos mensuales, una mujer percibió 7,905 pesos; es decir, 4,111 pesos menos al mes, "},{type:b,tag:c,props:{},children:[{type:a,value:"por el mismo trabajo"}]},{type:a,value:"."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"Además de las cifras de la ENIGH, hay diversos estudios de organismos, como la Organización Internacional del Trabajo (OIT), que demuestran año tras año que las mujeres en México ganamos menos que los hombres en la mayoría de los sectores. Además, dejan ver que "},{type:b,tag:c,props:{},children:[{type:a,value:"esta disparidad se acentúa en puestos de liderazgo y en sectores tradicionalmente masculinizados"}]},{type:a,value:" (el sector salud o las ingenierías, por mencionar dos ejemplos), aunque, desafortunadamente, también persiste en profesiones donde las mujeres son mayoría (el magisterio o el sector servicios, e inclusive en sectores laborales precarizados)."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:b,tag:c,props:{},children:[{type:a,value:"Esta brecha, además de ser una  injusticia social, también representa un freno para el desarrollo económico y la equidad en el país."}]},{type:a,value:" Es un eco de prejuicios y estereotipos arraigados en nuestra cultura, donde ser mujer, en muchas ocasiones, es sinónimo de enfrentar puertas cerradas o salarios inferiores. Y si eres madre, el panorama es más complejo, pues la sociedad aún nos carga con el peso desproporcionado de los cuidados y las responsabilidades del hogar, obligándonos a elegir entre nuestras carreras y nuestra familia, o nuestro crecimiento profesional."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"¿Por qué existen y persisten estas brechas salariales, en perjuicio de las mujeres? Las causas son muchas, además de complejas. Entre ellas, se encuentran:"}]},{type:a,value:d},{type:b,tag:"ul",props:{},children:[{type:a,value:d},{type:b,tag:f,props:{},children:[{type:b,tag:c,props:{},children:[{type:a,value:"La discriminación,"}]},{type:a,value:" que se fundamenta en prejuicios y estereotipos de género que limitan el acceso de las mujeres a ciertos puestos o que justifican salarios más bajos,"}]},{type:a,value:d},{type:b,tag:f,props:{},children:[{type:b,tag:c,props:{},children:[{type:a,value:"Las responsabilidades de cuidado no compartidas,"}]},{type:a,value:" asumidas fundamentalmente por las mujeres, pues en nuestro país y por mandato cultural la carga desproporcionada de las labores domésticas y de cuidados recae en las mujeres, lo que a menudo nos obliga a optar por trabajos de medio tiempo o con menor remuneración para conciliar la vida laboral y familiar,"}]},{type:a,value:d},{type:b,tag:f,props:{},children:[{type:b,tag:c,props:{},children:[{type:a,value:"La infravaloración de las habilidades y el trabajo desempeñados por mujeres"}]},{type:a,value:", especialmente en labores que se perciben como “femeninas”,"}]},{type:a,value:d},{type:b,tag:f,props:{},children:[{type:b,tag:c,props:{},children:[{type:a,value:"La falta de transparencia salarial"}]},{type:a,value:", que se observa en la falta de políticas claras y transparentes sobre las remuneraciones, que dificulta la identificación y corrección de las disparidades,"}]},{type:a,value:d},{type:b,tag:f,props:{},children:[{type:b,tag:c,props:{},children:[{type:a,value:"La menor participación de las mujeres en puestos directivos,"}]},{type:a,value:" los cuales tienen, casi siempre, los salarios más elevados, pero donde no hay una representación significativa de mujeres, y finalmente,"}]},{type:a,value:d},{type:b,tag:f,props:{},children:[{type:b,tag:c,props:{},children:[{type:a,value:"La segregación ocupacional,"}]},{type:a,value:" lo cual significa que las mujeres se concentran en sectores y ocupaciones peor remuneradas, en muchas ocasiones en sectores laborales precarios (por ejemplo, servicios o trabajos de cuidado no reconocidos)."}]},{type:a,value:d}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"Las consecuencias de esta brecha salarial son profundas, e impactan en muchos aspectos de la vida de las mujeres: en nuestra autonomía económica, en nuestra capacidad de ahorro presente y futuro, y en el acceso limitado a pensiones dignas. Este tipo de consecuencias, a largo plazo, conlleva a la "},{type:b,tag:c,props:{},children:[{type:a,value:"mayor vulnerabilidad de las mujeres a caer o permanecer en situación de pobreza, especialmente en la vejez"}]},{type:a,value:", y también a perpetuar "},{type:b,tag:c,props:{},children:[{type:a,value:"ciclos de desigualdad intergeneracional"}]},{type:a,value:", así como a limitar el crecimiento económico del país al desaprovechar el talento y el potencial de la mitad de su población."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"Es hora de romper esta inercia. México necesita un cambio radical para cerrar esta brecha, y para lograrlo necesitamos de la "},{type:b,tag:c,props:{},children:[{type:a,value:"colaboración de diversos actores"}]},{type:a,value:". Desde el gobierno se deben implementar "},{type:b,tag:c,props:{},children:[{type:a,value:"políticas públicas que realmente se enfoquen en impulsar  la igualdad salarial"}]},{type:a,value:", como la legislación de transparencia salarial, la fiscalización de empresas y la promoción de licencias parentales equitativas. Por parte de las empresas, necesitamos que asuman  un compromiso y que adopten "},{type:b,tag:c,props:{},children:[{type:a,value:"políticas de no discriminación"}]},{type:a,value:", que realicen "},{type:b,tag:c,props:{},children:[{type:a,value:"auditorías salariales internas"}]},{type:a,value:", que promuevan la "},{type:b,tag:c,props:{},children:[{type:a,value:"participación de mujeres en puestos de liderazgo"}]},{type:a,value:", ofreciendo la flexibilidad que necesitan. Desde la sociedad civil, requerimos de organizaciones que continúen alzando la voz, "},{type:b,tag:c,props:{},children:[{type:a,value:"visibilicen la problemática"}]},{type:a,value:", eduquen sobre los "},{type:b,tag:c,props:{},children:[{type:a,value:"derechos laborales de las mujeres"}]},{type:a,value:" y aboguen por un "},{type:b,tag:c,props:{},children:[{type:a,value:"cambio cultural"}]},{type:a,value:" que valore equitativamente el trabajo de hombres y mujeres. Finalmente, las personas también debemos ser conscientes de esta realidad, buscando negociar salarios justos y apoyando a las mujeres en el ámbito laboral."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"Cerrar la brecha salarial de género es un "},{type:b,tag:c,props:{},children:[{type:a,value:"asunto de justicia social,"}]},{type:a,value:" además de una necesidad económica, una inversión en nuestro futuro y un pilar para construir un México más equitativo y próspero para todas y todos. Es hora de pasar de las palabras a la acción y asegurar que "},{type:b,tag:c,props:{},children:[{type:a,value:"el trabajo de las mujeres sea valorado y remunerado justamente"}]},{type:a,value:", y que la igualdad salarial no sea solamente un “día de reflexión”, ni una idea aspiracional."}]},{type:a,value:d}]},dir:j,path:"\u002Fcolumnas\u002Fla_persistente_brecha_salarial_de_genero_en_mexico",extension:k,createdAt:m,updatedAt:m},columnas:[{slug:"arriba_las_sirenas_negras",title:"¡Arriba las sirenas negras!",date:"2023-03-21T17:00:05.207Z",img:"https:\u002F\u002Fucarecdn.com\u002F4a69a88d-6432-46c0-9f15-96253c5a619b\u002F","img-alt":"Inclusión",autor:"Berenice Valencia",medio:l,link:"https:\u002F\u002Fwww.animalpolitico.com\u002Fanalisis\u002Finvitades\u002Farriba-las-sirenas-negras",category:h,extracto:"El racismo no se reduce a discriminación y para eliminarlo no es suficiente la representación en medios. El racismo es también la distribución desigual de recursos y poder que clasifica a las personas de acuerdo a ciertas características que se han construido socialmente como “razas”.",toc:[],body:{type:i,children:[{type:b,tag:e,props:{},children:[{type:a,value:"En septiembre del año pasado, "},{type:b,tag:c,props:{},children:[{type:a,value:"Disney"}]},{type:a,value:" estrenó el trailer de su nueva versión de "},{type:b,tag:c,props:{},children:[{type:a,value:"La Sirenita"}]},{type:a,value:", donde Halle Bailey, una actriz negra, interpreta a la sirena Ariel. Con las primeras imágenes de la "},{type:b,tag:c,props:{},children:[{type:a,value:"película"}]},{type:a,value:" llegaron críticas simplonas de adultos indignados por un "},{type:b,tag:g,props:{},children:[{type:a,value:"casting"}]},{type:a,value:" que, decían, arruinaba sus infancias, y por videos de niñas emocionadas por verse reflejadas en Ariel. También surgieron artículos explicando acertadamente por qué la indignación de esos adultos viene del racismo y por qué es importante que las infancias negras se vean representadas en la pantalla grande."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"Meses antes, cuando no había trailer pero ya sabíamos que Halle Bailey sería Ariel, se volvió popular el video de una niña a quien le preguntan en la calle qué opina al respecto y ella, sin inmutarse, contesta: “no las tenemos que discriminar, arriba las "},{type:b,tag:c,props:{},children:[{type:a,value:"sirenas negras"}]},{type:a,value:"”. Me parece un gran mensaje para este "},{type:b,tag:c,props:{},children:[{type:a,value:"Día Internacional de la Eliminación de la Discriminación Racial"}]},{type:a,value:". No es suficiente con no discriminar, hay que celebrar la representación de la diversidad. Sin embargo, yo agregaría que es importante llevar nuestras conversaciones sobre racismo más allá de la discriminación y la representación."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"En México, hasta hace un par de años las conversaciones sobre racismo eran prácticamente inexistentes. La idea de que México es clasista, pero no racista (como si eso fuera aceptable) no se cuestionaba. Recientemente se ha popularizado el cuestionar, al menos, la falta de representación en medios. Esto se debe, en buena medida, a "},{type:b,tag:c,props:{},children:[{type:a,value:"Poder Prieto"}]},{type:a,value:", una colectiva conformada principalmente por actrices y actores que han denunciado la discriminación racial en la industria del entretenimiento. Actores con mucha visibilidad como Tenoch Huerta y Maya Zapata han impulsado las discusiones sobre por qué en casi todos los programas de televisión, películas y comerciales mexicanos, los actores son blancos."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"Que los protagonistas de nuestras historias sean siempre blancos en un país como México -donde el 19 % de la población se autoidentifica como indígena, el 2 % como afrodescendiente y el 67 % autoclasifica su piel en tonos morenos- muestra una evidente discriminación racial. Discriminar significa tratar de forma diferenciada y despreciativa a una persona o grupo debido a nuestros prejuicios respecto a ese grupo. En este caso, es lo que sucede no solamente durante los "},{type:b,tag:g,props:{},children:[{type:a,value:n}]},{type:a,value:" sino en las salas donde se escriben los guiones y detrás de las cámaras de las producciones mediáticas. México y el mundo se nos presentan como si sólo existieran cierto tipo de personas, como si nuestra empatía y nuestras narrativas sólo pudieran tratarse de gente blanca. Nos presentan la blanquitud como realidad única y como aspiración."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"La discriminación, por supuesto, es un problema grave. Sin embargo, el racismo no se reduce a discriminación y para eliminarlo no es suficiente la representación en medios. El racismo no sólo es que no aparezcan personas negras o de pueblos originarios en la portada de Quien. El racismo (también) es la distribución desigual de recursos y poder que clasifica a las personas de acuerdo a ciertas características que se han construido socialmente (sin fundamento biológico, por cierto) como “razas”."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"Entonces, el racismo está en los "},{type:b,tag:g,props:{},children:[{type:a,value:n}]},{type:a,value:" de Televisa, sí, pero también está en el hecho de que, en México, las personas afrodescendientes tienen un mayor porcentaje de analfabetismo y menos acceso al agua entubada. Está en el sistema de salud y de justicia cuando no garantizan el acceso a sus servicios en lenguas de pueblos originarios. El racismo está en la falta de datos sobre la situación económica de la población afrodescendiente y en el despojo y contaminación de las tierras de pueblos originarios."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"Existen diversos colectivos como Copera, Afrontera, Kumoontun, entre otras, que nos proporcionan claves para expandir la conversación sobre el racismo y para exigir no sólo cambios de comportamiento individual sino políticas públicas que contribuyan a eliminarlo. La discriminación racial no se terminará si no atendemos el racismo estructural. Así que, celebremos a las sirenas, superheroínas y protagonistas negras y de pueblos originarios, pero hagámoslo sabiendo que la representación no soluciona la desigualdad estructural. Debemos exigir más."}]}]},dir:j,path:"\u002Fcolumnas\u002Farriba_las_sirenas_negras",extension:k,createdAt:"2023-06-19T05:11:57.400Z",updatedAt:"2023-05-30T23:46:33.649Z"},{slug:"caravana_migrante_el_mas_reciente_reto_de_politica_exterior",title:"Caravana migrante, el más reciente reto de política exterior",date:"2019-01-21T20:32:25.569Z",img:"https:\u002F\u002Fucarecdn.com\u002Fee24c242-c206-4976-a9c9-0bec75c19113\u002F",autor:"Ana Paula Sandoval",medio:"Expansion ",link:"https:\u002F\u002Fexpansion.mx\u002Fopinion\u002F2019\u002F01\u002F21\u002Fopinion-caravana-migrante-el-mas-reciente-reto-de-politica-exterior",category:h,extracto:o,toc:[],body:{type:i,children:[{type:b,tag:e,props:{},children:[{type:b,tag:g,props:{},children:[{type:a,value:"López Obrador tiene una gran oportunidad de convertirse en un ejemplo mundial de cómo enfrentarse y resolver una problemática que ha caracterizado al siglo XXI, opina Ana Paula Sandoval."}]}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:o}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"En esa ocasión, los migrantes centroamericanos se enfrentaron a la violencia y represión de parte de la policía mexicana que con equipos antimotines les impidió –por poco tiempo- el paso, dando lugar a una ola de violencia. Esta acción fue fuertemente criticada señalando que México accedió a hacer el “"},{type:b,tag:g,props:{},children:[{type:a,value:"trabajo sucio"}]},{type:a,value:"” a Estados Unidos, país que ha tomado una postura extremadamente crítica y restrictiva ante estos fenómenos migratorios."}]}]},dir:j,path:"\u002Fcolumnas\u002Fcaravana_migrante_el_mas_reciente_reto_de_politica_exterior",extension:k,createdAt:"2023-06-19T05:11:57.476Z",updatedAt:"2022-08-22T22:00:47.046Z"},{slug:"como_aumentar_la_productividad_en_mexico",title:"¿Cómo aumentar la productividad en México?",date:"2014-12-12T20:59:19.115Z",img:"https:\u002F\u002Fucarecdn.com\u002Fb0f9f150-1650-4570-bd56-b8aa1e6719f8\u002F",autor:"José Luis Chicoma, Eduardo Sierra",medio:" El punto sobre la i",link:"https:\u002F\u002Fmedia.wix.com\u002Fugd\u002F5a5f52_ea39ffab127545e589bd08be024e7b60.pdf",category:h,extracto:p,toc:[],body:{type:i,children:[{type:b,tag:e,props:{},children:[{type:a,value:p}]}]},dir:j,path:"\u002Fcolumnas\u002Fcomo_aumentar_la_productividad_en_mexico",extension:k,createdAt:"2023-06-19T05:11:57.536Z",updatedAt:"2022-08-22T22:00:47.047Z"}]}],fetch:{},mutations:[]}}("text","element","strong","\n","p","li","em","inclusion","root","\u002Fcolumnas",".md","Animal Político","2025-11-25T01:24:03.244Z","castings","El martes pasado una nueva caravana migrante, conformada inicialmente por unas 500 personas (y que actualmente supera las 2,000), partió de Honduras con miras de llegar a Estados Unidos en busca del sueño americano. Este episodio se repite después de que una primera caravana emprendiera su camino el 13 de octubre del año pasado.","La generación de mayor conocimiento, no sólo se traduce en mejores condiciones laborales, también genera efectos positivos en la economía.")));